def get_pairs_count(arr, target_sum, count):
    arr.sort()  # Sort the array to make it easier to find pairs
    left, right = 0, len(arr) - 1

    while left < right:
        current_sum = arr[left] + arr[right]

        if current_sum == target_sum:
            count += 1
            left += 1
            right -= 1
        elif current_sum < target_sum:
            left += 1
        else:
            right -= 1

    return count
```

